function editMoveMap(mt){let m=MOVEMAP.find(x=>x.movement_type===mt)||{movement_type:mt,exposure_bucket:'REVIEW',factor:0,notes:''};$('mmType').value=mt;$('mmBucket').value=m.exposure_bucket;$('mmFactor').value=String(m.factor);$('mmNotes').value=m.notes||'';$('mmMsg').classList.add('hidden');syncMoveFactor();$('movementMapModal').classList.add('show')}window.editMoveMap=editMoveMap;
function syncMoveFactor(){let b=$('mmBucket').value;if(!['IN','OUT'].includes(b)){$('mmFactor').value='0';$('mmFactor').disabled=true}else $('mmFactor').disabled=false}
$('mmBucket').onchange=syncMoveFactor;
$('saveMoveMap').onclick=async()=>{let msg=$('mmMsg'),payload={movement_type:$('mmType').value,exposure_bucket:$('mmBucket').value,factor:Number($('mmFactor').value),notes:$('mmNotes').value.trim()};try{await rpc('breakage_movement_map_save_v51',{p_payload:payload});msg.classList.remove('hidden');msg.style.color='#079455';msg.textContent='✓ Mapping tersimpan. Movement existing juga direclassify.';await loadMovementMap();setTimeout(()=>{$('movementMapModal').classList.remove('show')},500);await loadAll()}catch(e){msg.classList.remove('hidden');msg.style.color='#c42d26';msg.textContent='Gagal: '+cleanErr(e.message)}};
$('smFile').onchange=e=>{if(e.target.files[0])handleMovementFile(e.target.files[0])};
function handleMovementFile(file){let msg=$('smMsg');msg.classList.remove('hidden');msg.style.color='#6f7b91';msg.textContent='Membaca MB51 movement…';let fr=new FileReader();fr.onload=async e=>{try{let wb=XLSX.read(e.target.result,{type:'binary',cellDates:true}),rows=parseMovementMB51(wb);if(!rows)throw new Error('MB51 tidak dikenali. Pastikan Posting Date, Movement Type, Quantity dan Name 1/RDC tersedia.');let groups={};for(const r of rows){let period=r.posting_date.slice(0,7),k=r.rdc_name+'|'+period;(groups[k]||(groups[k]=[])).push(r)}let results=[];for(const [k,rr] of Object.entries(groups)){let [rdc,period]=k.split('|');if(!RDC_LIST.includes(rdc))continue;if(period!==PERIOD)continue;if(!ACCESS.is_master&&rdc!==ACCESS.rdc_name)continue;results.push(await rpc('breakage_movement_stage_v51',{p_filename:file.name,p_mode:$('smMode').value,p_rows:rr}))}if(!results.length)throw new Error(`Tidak ada baris ${PERIOD} untuk scope login/RDC yang valid.`);let reviews=results.reduce((a,b)=>a+Number(b.review_rows||0),0);$('smPreview').innerHTML=`<div class="section-title">Hasil Upload</div><div class="tablewrap"><table class="tbl"><thead><tr><th>RDC</th><th>Periode</th><th>Data s.d.</th><th>Rows</th><th>Mapped</th><th>Review</th><th>Status</th></tr></thead><tbody>${results.map(r=>`<tr><td>${esc(r.rdc)}</td><td>${esc(r.period)}</td><td>${esc(r.data_through_date)}</td><td>${fmt(r.total_rows)}</td><td>${fmt(r.mapped_rows)}</td><td>${fmt(r.review_rows)}</td><td>${kpiStatusPill(r.status==='READY'?'PROVISIONAL':r.status)}</td></tr>${r.review_rows?`<tr><td colspan="7"><b>Unknown:</b> ${(r.unknown_movement_types||[]).map(u=>`${esc(u.movement_type)} (${u.rows}) ${ACCESS.is_master?`<button class="secondary" onclick="editMoveMap('${esc(u.movement_type)}')">Map</button>`:''}`).join(' · ')}</td></tr>`:''}`).join('')}</tbody></table></div>`;msg.style.color=reviews?'#b65f00':'#079455';msg.textContent=reviews?`Upload berhasil, tetapi ${reviews} row memerlukan mapping sebelum KPI dapat dihitung.`:'✓ Upload berhasil. KPI Warehouse MTD diperbarui sebagai PROVISIONAL.';await loadAll()}catch(x){msg.style.color='#c42d26';msg.textContent='Gagal: '+cleanErr(x.message)}};fr.readAsBinaryString(file)}
const PLATE_RE=/\b[A-Z]{1,2}\s?\d{3,5}\s?[A-Z]{1,3}\b/;let UPLOAD=null;
function classify(dht,mvt){let t=String(dht||'').toUpperCase();if(PLATE_RE.test(t))return{main:'delivery',sub:'Transport'};if(mvt==='602')return{main:'delivery',sub:'Loading'};if(/PECAH/.test(t)&&/PALET|PALLET/.test(t))return{main:'warehouse',sub:'Packaging / Pallet'};if(/PERSIAPAN/.test(t))return{main:'warehouse',sub:'Handling / Picking'};if(/PERAPIHAN|\bSO\b|STOCK OPNAME|GUDANG/.test(t))return{main:'warehouse',sub:'Storage / Penyimpanan'};return{main:'warehouse',sub:'Other'}}
function parseMB51(wb){let sn=wb.SheetNames.find(n=>{let g=XLSX.utils.sheet_to_json(wb.Sheets[n],{header:1,defval:null}),h=(g[0]||[]).map(x=>String(x||'').trim());return h.includes('Posting Date')&&h.includes('Movement Type')&&h.includes('Storage Location')});if(!sn)return null;let g=XLSX.utils.sheet_to_json(wb.Sheets[sn],{header:1,defval:null,raw:true,cellDates:true}),h=g[0].map(x=>String(x||'').trim()),c=n=>h.indexOf(n),cd=c('Posting Date'),cq=c('Quantity'),cs=c('Storage Location'),cm=c('Movement Type'),ch=c('Document Header Text'),cr=c('Name 1'),cma=c('Material'),cde=c('Material Description'),cdo=c('Material Document');if([cd,cq,cs,cm,ch,cr].some(x=>x<0))return null;let out=[];for(let i=1;i<g.length;i++){let r=g[i],mt=String(r[cm]||'').trim(),q=Number(r[cq])||0,d=r[cd];if(!(d instanceof Date))continue;let sl=String(r[cs]||''),cls,qty;if(mt==='311'&&sl==='RFB1'&&q>0){qty=q;cls=classify(r[ch],mt)}else if(mt==='602'){qty=Math.abs(q);cls=classify(r[ch],mt)}else continue;let rdc=String(r[cr]||'').trim().replace(/^RDC\s+/i,'');out.push({rdc,period:d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-01',posting_date:d.toISOString().slice(0,10),main_category:cls.main,sub_category:cls.sub,material:cma>=0?String(r[cma]||''):'',material_desc:cde>=0?String(r[cde]||''):'',qty,sap_document:cdo>=0?String(r[cdo]||''):'',driver_vendor:cls.sub==='Transport'?String(r[ch]||''):'',movement_type:mt,storage_location:sl,document_header_text:String(r[ch]||'')})}return out.length?out:null}
function steps(n){return `<div class="steps">${['Upload SAP','Preview','Reconcile','Publish'].map((x,i)=>`<div class="step ${i+1<=n?'active':''}"><i>${i+1<n?'✓':i+1}</i>${x}</div>`).join('')}</div>`}
function openRecon(){if(!ACCESS?.is_master&&ACCESS?.role!=='rdc_manager'){}$('reconModal').classList.add('show');recon1()}window.openRecon=openRecon;
function recon1(){$('reconWizard').innerHTML=steps(1)+`<div class="photo-area" style="text-align:center;padding:34px"><b>Upload SAP MB51</b><div class="smallnote" style="margin:8px">Format .xlsx / .xls · parser existing Movement 311 → RFB1 & reversal 602</div><label for="mb51" class="secondary" style="display:inline-block">Pilih File</label><input type="file" id="mb51" accept=".xlsx,.xls" hidden><div id="mbmsg" style="margin-top:10px"></div></div>`;$('mb51').onchange=e=>{if(e.target.files[0])handleMB(e.target.files[0])}}
function handleMB(file){let msg=$('mbmsg');msg.textContent='Membaca file…';let fr=new FileReader();fr.onload=async e=>{try{let wb=XLSX.read(e.target.result,{type:'binary',cellDates:true}),rows=parseMB51(wb);if(!rows)throw new Error('File MB51 tidak dikenali / kolom wajib tidak ditemukan.');let res=await rpc('breakage_stage',{p_filename:file.name,p_rows:rows});UPLOAD=res;recon2(res)}catch(x){msg.textContent='Gagal: '+cleanErr(x.message)}};fr.readAsBinaryString(file)}
function recon2(r){let cats=Object.entries(r.by_category||{});$('reconWizard').innerHTML=steps(2)+`<div class="section-title">${esc(r.rdc)} · ${esc(r.period)} · ${fmt(r.total_rows)} baris</div><table class="tbl"><thead><tr><th>Kategori</th><th>Sub</th><th>Qty</th><th>Rows</th></tr></thead><tbody>${cats.map(([k,v])=>{let[m,s]=k.split('|');return`<tr><td>${esc(m)}</td><td>${esc(s)}</td><td>${fmt(v.qty)}</td><td>${fmt(v.rows)}</td></tr>`}).join('')}</tbody></table><button class="primary" style="margin-top:12px" id="reconNext">Lanjut Reconciliation →</button>`;$('reconNext').onclick=recon3}
async function recon3(){$('reconWizard').innerHTML=steps(3)+'<div class="empty">Membandingkan dengan existing…</div>';try{let r=await rpc('breakage_reconcile',{p_upload_id:UPLOAD.upload_batch_id}),rows=r.detail||[];$('reconWizard').innerHTML=steps(3)+`<div class="tablewrap"><table class="tbl"><thead><tr><th>Kategori</th><th>Sub</th><th>Existing</th><th>SAP</th><th>Variance</th><th>Status</th><th>Decision</th></tr></thead><tbody>${rows.map((x,i)=>`<tr><td>${esc(x.main_category)}</td><td>${esc(x.sub_category)}</td><td>${fmt(x.existing_qty)}</td><td>${fmt(x.sap_qty)}</td><td>${fmt(x.variance)}</td><td>${esc(x.status)}</td><td><select id="dec${i}"><option value="USE_SAP" ${x.status!=='MATCH'?'selected':''}>Pakai Data SAP</option><option value="KEEP_EXISTING">Pertahankan Existing</option><option value="SKIP">Lewati</option></select></td></tr>`).join('')}</tbody></table></div><button class="primary" style="margin-top:12px" id="pubNext">Lanjut Confirm & Publish →</button>`;$('pubNext').onclick=()=>recon4(rows.map((x,i)=>({main_category:x.main_category,sub_category:x.sub_category,action:$('dec'+i).value})))}catch(e){$('reconWizard').innerHTML='<div class="errorbox">'+esc(cleanErr(e.message))+'</div>'}}
function recon4(dec){$('reconWizard').innerHTML=steps(4)+`<div class="hint">Publish hanya setelah review. Keputusan ini akan menjadi monthly transactional control.</div><div id="pubmsg" style="margin:12px 0"></div><button class="primary" id="publish">✓ Confirm & Publish</button>`;$('publish').onclick=async()=>{try{$('pubmsg').textContent='Publishing…';await rpc('breakage_publish',{p_upload_id:UPLOAD.upload_batch_id,p_decisions:dec});$('pubmsg').innerHTML='<span class="good">✓ Published.</span>';setTimeout(async()=>{$('reconModal').classList.remove('show');await loadAll()},900)}catch(e){$('pubmsg').textContent='Gagal: '+cleanErr(e.message)}}}
function exportExcel(){let wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(RDCROWS),'RDC Comparison');XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(INCIDENTS),'Incident');XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(TARGETS),'Recovery Target');XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(KPI_SETTINGS),'Management Target');XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(EXPOSURE?.rows||[]),'Warehouse Exposure');XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(MOVEH||[]),'SAP Movement Upload');XLSX.writeFile(wb,`SLS_Breakage_${PERIOD}_${SCOPE}.xlsx`)}window.exportExcel=exportExcel;
function toast(msg,type){console[type==='bad'?'error':'log'](msg)}
restoreSession();
